import Root from "./2Managing State/PPassingDataDeeply/Simplify"
import {HandleInput as Fundamental} from "./2Managing State/4zBaseConcept"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"

import { createContext } from "react"
import { useContext } from "react"

const Context = createContext(1)

function Section({level, children}) {
  return 
  <section>
    <Context.Provider>{children}</Context.Provider>
  </section>
}

function Header({children}) {
  const level = useContext(Context)
  switch(level) {
    case 1:
      return <h1>{children}</h1>
    case 2:
      return "akan saya lawan!!!"
  }
}

export default function () {
  return <>
  <Section level={1}>
    <Header>tes</Header>
  </Section>
  </>
}



